 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the full-length, non-background separator line.
    axis = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            axis = ("row", r, grid[r][0])
            break
    if axis is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and grid[0][c] != bg:
                axis = ("col", c, grid[0][c])
                break
    if axis is None:
        return [row[:] for row in grid]

    orient, ai, axis_color = axis
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != axis_color]
    if not pts:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if orient == "row":
        top, bottom = min(r for r, c in pts), max(r for r, c in pts)
        if top > ai:
            shift = ai + 1 - top
            marker = bottom + shift + 1
        else:
            shift = ai - 1 - bottom
            marker = top + shift - 1
        # Move the colored object flush against the separator.
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r + shift][c] = grid[r][c]
        if 0 <= marker < h:
            out[marker] = [8] * w
    else:
        left, right = min(c for r, c in pts), max(c for r, c in pts)
        if left > ai:
            shift = ai + 1 - left
            marker = right + shift + 1
        else:
            shift = ai - 1 - right
            marker = left + shift - 1
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            out[r][c + shift] = grid[r][c]
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8
    return out
